Method.Implementation:
#dim snapShot As EnsLib.SQL.Snapshot
set parentId = "", key ="",value = "", preFix1 = "", preFix2 = "", rowId = "", rowId2 = ""


set glbNm = "^ClaimsData." _clmType _ ".BatchNum" _ batchNum
set parentIdArr = -1
set parentPROVID = -1
set parentCLMDTLID = -1
set parentCLM = -1
set provNum = 1
set subNum = 1
set clmNum = 1
set diagNum = 1
set lookUpNum = 1
set hospNum = 1

set delim = ","

FOR snpCnt=1:1:11
{
	if (snpCnt = 8)
	{
		set snpCnt = 9 // Read CLMLIEXPLGROUPS (9) before CLMLIEXPI (8)
		$$$TRACE("snpCnt = 8 - 9")
	}
	elseif (snpCnt = 10)
	{
		set snpCnt = 8 // Read CLMLIEXPI (8) after CLMLIEXPLGROUPS (9) 
		$$$TRACE("snpCnt = 10 - 8")
	}
	elseif (snpCnt = 9)
	{
		set snpCnt = 10 // Read (9) (8)
		$$$TRACE("snpCnt = 9 - 10")
	}

	set snapShot = pResultSnapshots.GetAt(snpCnt)
	set colCnt = snapShot.GetColumnCount()
	if ($DATA(^ClaimsColumns(snpCnt)) = 0)
	{
		set createClaimsColumns = 1
	}
	else
	{
		set createClaimsColumns = 0
	}
	while snapShot.Next()
	{
		for colIn=1:1:colCnt
		{
			set colNm = $ZSTRIP(snapShot.GetColumnName(colIn),"<>WC")	
			set data = $ZSTRIP(snapShot.GetData(colIn),"<>WC")	

			// Store the Column names from the resultset
			if (colIn = 1)
			{
				if (createClaimsColumns = 1)
				{
					set ^ClaimsColumns(snpCnt) = $REPLACE(colNm, "_", "") // Remove "_"
				}
				set value = data
			}
			else
			{
				if (createClaimsColumns = 1)
				{
					set ^ClaimsColumns(snpCnt) = ^ClaimsColumns(snpCnt) _"#~#" _ $REPLACE(colNm, "_" , "")
				}
				set value = value _"#~#" _ data
			}
			if (colIn=colCnt)
			{
				// Last field, save the record


				// $$$TRACE("Save:- snapShot: " _ snpCnt _", Parent: " _ parentId _ ", row Ids: "_ rowId _", " _ rowId2)

				if (parentId = "")
				{	
				   set @glbNm@(key) = value
				}
				else
				{
					set parentIdArr(preFix1_rowId) = parentId _ delim_ preFix1_rowId

					SET count=$LENGTH(parentId,delim)
					if (count >= 2)
					{
						set key1 =$PIECE(parentId,delim,1)
						if (count = 2)
						{
							set key2 =$PIECE(parentId,delim,2)
							set @glbNm@(key1 , key2 , preFix1_rowId) = value
						}
						elseif (count = 3)
						{
							set key2 =$PIECE(parentId,delim,2)
							set key3 =$PIECE(parentId,delim,3)
							set @glbNm@(key1 , key2 , key3 , preFix1_rowId) = value
						}
						elseif (count = 4)
						{
							set key2 =$PIECE(parentId,delim,2)
							set key3 =$PIECE(parentId,delim,3)
							set key4 =$PIECE(parentId,delim,4)
							set @glbNm@(key1 , key2 , key3 , key4 , preFix1_rowId) = value
						}
						elseif (count = 5)
						{
							set key2 =$PIECE(parentId,delim,2)
							set key3 =$PIECE(parentId,delim,3)
							set key4 =$PIECE(parentId,delim,4)
							set key5 =$PIECE(parentId,delim,5)
							set @glbNm@(key1 , key2 , key3 , key4 , key5 , preFix1_rowId) = value
						}
					}
					else
					{
						set @glbNm@(parentId , preFix1_rowId) = value
					}


					if (rowId2 '= "") // CLCLID
					{
						set parentIdArr(preFix2_rowId2) = parentId _ delim_ preFix2_rowId2
						// $$$TRACE("parentIdArr: " _ preFix2_rowId2 _" = " _ parentId _ delim_ preFix2_rowId2)
						set rowId2 = ""													
					}
				}

				set parentId = ""
			}
			else
			{
				if ((snpCnt=1) && (colNm = "CLM_PROV_ID")) // BILLPROV - ROW_BILL_PROV
				{					
					set key = claimsCount + provNum _"-" _ data
					set parentPROVID(data) = key
					Do $INCREMENT(provNum)
				}
				elseif (snpCnt=2)  // SUBSC - ROW_SUBSC
				{
					set preFix1 = "SUBSC-"
					if (colNm = "PARENT_CLM_PROV_ID")
					{
						set parentId = parentPROVID(data)
					}
					elseif (colNm = "CLM_MBR_ID_AND_CLM_SET")
					{
						set rowId = claimsCount + subNum _"-" _ data
						set parentSUBSC(data) = rowId
						Do $INCREMENT(subNum)
					}				
				}

				elseif (snpCnt=3) // CLAIM - ROW_CLAIM
				{
					set preFix1 = "CLAIM-"
					set preFix2 = "CLCLID-"
					if (colNm = "PARENT_CLM_MBR_ID_AND_CLM_SET")
					{

						set subcId = parentSUBSC(data)						
						set parentId = parentIdArr("SUBSC-"_subcId)
					}
					elseif ( colNm = "CLM_HDR_ID")
					{				
						set rowId = claimsCount + clmNum _"-" _ data
						set parentCLM(data) = rowId
						Do $INCREMENT(clmNum)
					}
					elseif ( colNm = "CLCL_ID")
					{
						set rowId2 = data					
					}

				}

				elseif (snpCnt=4) // HSOP - ROW_HOSP
				{
					set preFix1 = "HOSP-"
					if ( colNm = "PARENT_CLM_HDR_ID")
					{
						set clmId = parentCLM(data)
						set parentId = parentIdArr("CLAIM-"_clmId)
					}
					elseif (colNm = "CLHP_MED_REC_NO")
					{
						set rowId = data
						if (data = "")
						{
							set rowId = hospNum
							Do $INCREMENT(hospNum)
						}


					}
				}
				elseif (snpCnt=5) // DIAG - WRK_MEDICARE_CLM_DIAG
				{
					set preFix1 = "DIAG-"
					if ( colNm = "LOOKUP_KEY")
					{
						set lookKey = $E(data, 1, $F(data, "-")-2)
						// $$$TRACE("DIAG Look for: " _ lookKey)
						set parentId = parentIdArr("CLCLID-"_ lookKey) 
					}
					elseif (colNm = "IDCD_ID")
					{
						set rowId = claimsCount + diagNum _"-" _ data

						Do $INCREMENT(diagNum)
					}
				}
				elseif (snpCnt=6) // ATNDPROV - ROW_ATND_PROV
				{
					set preFix1 ="ATND-"
					if ( colNm = "PARENT_CLM_HDR_ID")
					{
						set clmId = parentCLM(data)
						set parentId = parentIdArr("CLAIM-"_clmId)
					}
					elseif (colNm = "CLM_PROV_ID")
					{
						set rowId = data
					}
				}
				elseif (snpCnt=7) // CLMLI - ROW_CLM_LI_PLUS_NDC
				{
					set preFix1 ="CLMLI-"
					if ( colNm = "PARENT_CLM_HDR_ID")
					{
						set clmId = parentCLM(data)
						set parentId = parentIdArr("CLAIM-"_clmId)
					}
					elseif (colNm = "CLM_DTL_ID")
					{
						set rowId = data
					}
					elseif (colNm = "CDML_SEQ_NO")
					{
						set clmliKey = claimsCount + data _"-" _ rowId
						set parentCLMDTLID(rowId) = clmliKey
						set rowId = clmliKey
					}

				}
				elseif (snpCnt=8) // CLMLIEXPI - CLM_LI_EXPI 
				{
					set preFix1 = "CLMLIEXPLREC-"
					if ( colNm = "PARENT_CLM_DTL_ID")
					{
						set clmId = parentCLMDTLID(data)
						set parentId = parentIdArr("CLMLI-"_clmId)
					}
					elseif (colNm = "CDML_AND_GROUP")
					{
						set rowId = data
					}
					elseif (colNm = "EXPL_SEQ_NO")
					{
						set rowId = claimsCount +data _"-" _ rowId
					}

				}

				elseif (snpCnt=9) // CLMLIEXPLGROUPS - ROW_CLM_LI_EXPL_GROUPS
				{
					set preFix1 ="CLMLIEXPLGROUP-"
					if ( colNm = "PARENT_CLM_DTL_ID")
					{
						set clmId = parentCLMDTLID(data)
						set parentId = parentIdArr("CLMLI-"_clmId)
					}
					elseif (colNm = "CDML_AND_GROUP")
					{
						set rowId = data
					}


				}

				elseif (snpCnt=10) // POCCUR - ROW_CLHO
				{
					set preFix1 = "LOOKUP-"
					if ( colNm = "LOOKUP_KEY")
					{
						set lookKey = $E(data, 1, $F(data, "-")-2)
						// $$$TRACE("snpCnt=10 - " _ data _ " - Look for: CLAIM: " _ lookKey)
						set clmId = parentCLM(lookKey)
						set parentId = parentIdArr("CLAIM-"_clmId)

						set key = data
						set rowId = data _"-" _ lookUpNum
						Do $INCREMENT(lookUpNum)						
					}

				}

				elseif (snpCnt=11) // PCOND - PCONDROW_CLHC
				{
					set preFix1 = "PCOND-"
					if ( colNm = "PARENT_CLM_HDR_ID")
					{
						set clmId = parentCLM(data)
						set parentId = parentIdArr("CLAIM-"_clmId)
					}
					elseif (colNm = "CLHC_SEQ_NO")
					{
						set rowId = data
					}
				}
			}

		}

	}

}

return $$$OK
